const triggerData = $('Execute Workflow Trigger').first().json || {};
const sheetRows = $input.all();

const queryObj = (triggerData.query && typeof triggerData.query === 'object') ? triggerData.query : {};
const action = String(triggerData.action || queryObj.action || 'retrieve').toLowerCase().trim();
const sheetId = String(triggerData.sheetId || queryObj.sheetId || '').trim();
const memoryIdInput = String(triggerData.memoryId || queryObj.memoryId || '').trim();
const memoryTypeInput = String(triggerData.memoryType || queryObj.memoryType || triggerData.type || queryObj.type || '').toLowerCase().trim();
const contentInput = String(triggerData.content || queryObj.content || triggerData.text || queryObj.text || '').trim();

let queryText = '';
if (typeof triggerData.queryText === 'string') queryText = triggerData.queryText;
else if (typeof triggerData.search === 'string') queryText = triggerData.search;
else if (typeof queryObj.search === 'string') queryText = queryObj.search;
else if (typeof queryObj.query === 'string') queryText = queryObj.query;
else if (typeof triggerData.query === 'string') queryText = triggerData.query;
queryText = queryText.trim();

let topicInput = '';
if (typeof triggerData.topic === 'string') topicInput = triggerData.topic;
else if (typeof queryObj.topic === 'string') topicInput = queryObj.topic;
else topicInput = queryText;
topicInput = topicInput.trim();

const statusInput = String(triggerData.status || queryObj.status || '').toLowerCase().trim();
const sourceTypeInput = String(triggerData.sourceType || queryObj.sourceType || 'user_explicit').trim();
const sourceMessageIdInput = String(triggerData.sourceMessageId || queryObj.sourceMessageId || '').trim();
const confidenceRaw = triggerData.confidence !== undefined ? triggerData.confidence : queryObj.confidence;
const confidence = confidenceRaw !== undefined && confidenceRaw !== null ? parseFloat(confidenceRaw) : (sourceTypeInput === 'user_explicit' ? 1.0 : 0.85);

let structuredVal = triggerData.structuredValue !== undefined ? triggerData.structuredValue : queryObj.structuredValue;
let structuredValStr = '';
if (structuredVal) {
  if (typeof structuredVal === 'object') {
    try { structuredValStr = JSON.stringify(structuredVal); } catch (e) { structuredValStr = ''; }
  } else {
    structuredValStr = String(structuredVal);
  }
}

const limitRaw = triggerData.limit !== undefined ? triggerData.limit : queryObj.limit;
const limit = limitRaw ? parseInt(limitRaw, 10) : 10;

// 1. Error Handling (Tab missing or API error)
const firstItem = sheetRows[0]?.json || {};
if (firstItem.error) {
  return [{
    json: {
      operationType: 'read_only',
      success: false,
      status: 'SHEET_TAB_NOT_FOUND',
      response: "⚠️ The 'Memories' tab was not found in your Google Sheet. Please add a tab named 'Memories' with columns: memoryId, memoryType, content, structuredValue, status, confidence, sourceMessageId, sourceType, createdAt, updatedAt, lastAccessedAt, embedding, schemaVersion.",
      error: firstItem.error
    }
  }];
}

// 2. Parse Existing Memories
const existingMemories = sheetRows
  .map(r => r.json)
  .filter(m => m && (m.memoryId || m.content) && m.row_number !== undefined);

function formatMemorySummary(memoriesList) {
  if (!memoriesList || memoriesList.length === 0) {
    return "No prior user memories or preferences recorded yet.";
  }
  let summary = '🧠 **Remembered User Context & Preferences (' + memoriesList.length + ' items):**\n';
  for (const m of memoriesList) {
    const typeTag = m.memoryType ? '[' + m.memoryType.toUpperCase() + ']' : '[NOTE]';
    const scoreStr = m.retrievalMethod === 'semantic_cosine' ? ' (relevance: ' + Math.round(m.relevance * 100) + '%)' : '';
    summary += '• ' + typeTag + ' ' + m.content + scoreStr + '\n';
  }
  return summary.trim();
}

// Cosine Similarity between two embedding float arrays
function cosineSimilarity(vecA, vecB) {
  if (!vecA || !vecB || vecA.length !== vecB.length) return 0;
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < vecA.length; i++) {
    dotProduct += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }
  if (normA === 0 || normB === 0) return 0;
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

// Fallback keyword relevance score (normalized to 0..1)
function scoreKeywordRelevance(content, queryStr) {
  if (!queryStr) return 1.0;
  const tokens = queryStr.toLowerCase().split(/\s+/).filter(t => t.length > 2);
  if (tokens.length === 0) return 1.0;
  const lowerContent = (content || '').toLowerCase();
  let matches = 0;
  for (const t of tokens) {
    if (lowerContent.includes(t)) matches += 1;
  }
  return matches / tokens.length;
}

// Helper: fetch embedding from local LM Studio text-embedding-nomic-embed-text-v1.5
async function fetchEmbedding(text) {
  if (!text || typeof text !== 'string' || text.trim().length === 0) return null;
  const configuredHost = (typeof process !== 'undefined' && (process.env.LM_STUDIO_HOST || process.env.EMBEDDING_HOST)) || '';
  const hosts = [
    ...(configuredHost ? [configuredHost] : []),
    'http://192.168.29.141:1234',
    'http://127.0.0.1:1234',
    'http://host.docker.internal:1234'
  ];

  const payload = {
    model: 'text-embedding-nomic-embed-text-v1.5',
    input: text.trim()
  };

  for (const host of hosts) {
    try {
      if (typeof $httpRequest === 'function') {
        const res = await $httpRequest({
          method: 'POST',
          url: host + '/v1/embeddings',
          body: payload,
          json: true,
          timeout: 2500
        });
        if (res && res.data && res.data[0] && Array.isArray(res.data[0].embedding)) {
          return res.data[0].embedding;
        }
      } else if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.httpRequest === 'function') {
        const res = await this.helpers.httpRequest({
          method: 'POST',
          url: host + '/v1/embeddings',
          body: payload,
          json: true,
          timeout: 2500
        });
        if (res && res.data && res.data[0] && Array.isArray(res.data[0].embedding)) {
          return res.data[0].embedding;
        }
      } else if (typeof fetch === 'function') {
        const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        const timer = controller ? setTimeout(() => controller.abort(), 2500) : null;
        const res = await fetch(host + '/v1/embeddings', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          signal: controller ? controller.signal : undefined
        });
        if (timer) clearTimeout(timer);
        if (res.ok) {
          const data = await res.json();
          if (data && data.data && data.data[0] && Array.isArray(data.data[0].embedding)) {
            return data.data[0].embedding;
          }
        }
      }
    } catch (e) {}
  }
  return null;
}

function generateMemoryId() {
  return 'mem_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6);
}

const nowIso = new Date().toISOString();

// ACTION: WRITE / RECORD / ADD
if (action === 'write' || action === 'add' || action === 'save' || action === 'record' || action === 'create') {
  if (!contentInput) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'MISSING_CONTENT',
        response: '⚠️ Content is required to store a memory.'
      }
    }];
  }

  const assignedType = memoryTypeInput || 'profile';
  const cleanNewContent = contentInput.toLowerCase().trim();

  // Duplicate / Idempotency check
  const existingDuplicate = existingMemories.find(m => {
    if (m.status !== 'active') return false;
    const cleanExisting = (m.content || '').toLowerCase().trim();
    return cleanExisting === cleanNewContent;
  });

  // Generate embedding using nomic-embed-text
  const embVector = await fetchEmbedding(contentInput);
  const embString = embVector ? JSON.stringify(embVector) : '';

  if (existingDuplicate) {
    const updatedRow = {
      row_number: existingDuplicate.row_number,
      memoryId: existingDuplicate.memoryId,
      memoryType: assignedType || existingDuplicate.memoryType,
      content: contentInput,
      structuredValue: structuredValStr || existingDuplicate.structuredValue || '',
      status: 'active',
      confidence: Math.max(existingDuplicate.confidence || 0, confidence),
      sourceMessageId: sourceMessageIdInput || existingDuplicate.sourceMessageId || '',
      sourceType: sourceTypeInput || existingDuplicate.sourceType || 'user_explicit',
      createdAt: existingDuplicate.createdAt || nowIso,
      updatedAt: nowIso,
      lastAccessedAt: nowIso,
      embedding: embString || existingDuplicate.embedding || '',
      schemaVersion: '1.0'
    };

    return [{
      json: {
        operationType: 'update',
        sheetId,
        row_number: existingDuplicate.row_number,
        memory: updatedRow,
        response: 'Memory already noted. Refreshed timestamp for: "' + contentInput + '".',
        isDuplicate: true,
        ...updatedRow
      }
    }];
  }

  let supersedeTarget = null;
  if (structuredValStr) {
    try {
      const parsedNew = JSON.parse(structuredValStr);
      if (parsedNew.key) {
        supersedeTarget = existingMemories.find(m => {
          if (m.status !== 'active' || !m.structuredValue) return false;
          try {
            const p = JSON.parse(m.structuredValue);
            return p.key === parsedNew.key;
          } catch (e) { return false; }
        });
      }
    } catch (e) {}
  }

  const newMemoryId = generateMemoryId();
  const newRow = {
    memoryId: newMemoryId,
    memoryType: assignedType,
    content: contentInput,
    structuredValue: structuredValStr,
    status: 'active',
    confidence: confidence,
    sourceMessageId: sourceMessageIdInput,
    sourceType: sourceTypeInput,
    createdAt: nowIso,
    updatedAt: nowIso,
    lastAccessedAt: nowIso,
    embedding: embString,
    schemaVersion: '1.0'
  };

  return [{
    json: {
      operationType: 'append',
      sheetId,
      memory: newRow,
      response: '🧠 Remembered: "' + contentInput + '" [' + assignedType + '].',
      supersededMemoryId: supersedeTarget ? supersedeTarget.memoryId : null,
      ...newRow
    }
  }];
}

// ACTION: RETRIEVE / LIST / SEARCH
if (action === 'retrieve' || action === 'list' || action === 'get' || action === 'search' || action === 'show') {
  const targetStatus = statusInput || 'active';
  let filtered = existingMemories.filter(m => {
    if (targetStatus !== 'all' && (m.status || 'active').toLowerCase() !== targetStatus) return false;
    if (memoryTypeInput && (m.memoryType || '').toLowerCase() !== memoryTypeInput) return false;
    return true;
  });

  if (queryText) {
    // Generate query embedding if query provided
    const queryEmb = await fetchEmbedding(queryText);

    filtered = filtered.map(m => {
      let score = 0;
      let method = 'keyword';
      if (queryEmb && m.embedding) {
        try {
          const memEmb = JSON.parse(m.embedding);
          if (Array.isArray(memEmb) && memEmb.length === queryEmb.length) {
            score = cosineSimilarity(queryEmb, memEmb);
            method = 'semantic_cosine';
          }
        } catch (e) {}
      }
      if (method === 'keyword') {
        score = scoreKeywordRelevance(m.content, queryText);
      }
      return {
        ...m,
        relevance: score,
        retrievalMethod: method
      };
    })
    .filter(m => {
      if (m.retrievalMethod === 'semantic_cosine') {
        return m.relevance > 0.25;
      }
      return m.relevance > 0;
    })
    .sort((a, b) => b.relevance - a.relevance || (new Date(b.updatedAt || 0) - new Date(a.updatedAt || 0)));
  } else {
    filtered.sort((a, b) => new Date(b.updatedAt || 0) - new Date(a.updatedAt || 0));
  }

  const results = filtered.slice(0, limit);
  const summaryText = formatMemorySummary(results);

  return [{
    json: {
      operationType: 'read_only',
      success: true,
      status: 'SUCCESS',
      action: 'retrieve',
      count: results.length,
      memories: results,
      response: summaryText,
      summaryText: summaryText
    }
  }];
}

// ACTION: UPDATE
if (action === 'update' || action === 'edit' || action === 'modify') {
  let matched = null;
  if (memoryIdInput) {
    matched = existingMemories.find(m => m.memoryId === memoryIdInput);
  } else if (contentInput) {
    matched = existingMemories.find(m => (m.content || '').toLowerCase().includes(contentInput.toLowerCase()));
  }

  if (!matched) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'MEMORY_NOT_FOUND',
        response: '⚠️ Could not find a memory matching ID/text to update.'
      }
    }];
  }

  let newEmbStr = matched.embedding || '';
  if (contentInput && contentInput !== matched.content) {
    const emb = await fetchEmbedding(contentInput);
    if (emb) newEmbStr = JSON.stringify(emb);
  }

  const updatedRow = {
    row_number: matched.row_number,
    memoryId: matched.memoryId,
    memoryType: memoryTypeInput || matched.memoryType,
    content: contentInput || matched.content,
    structuredValue: structuredValStr !== '' ? structuredValStr : (matched.structuredValue || ''),
    status: statusInput || matched.status || 'active',
    confidence: confidence !== undefined ? confidence : (matched.confidence || 1.0),
    sourceMessageId: sourceMessageIdInput || matched.sourceMessageId || '',
    sourceType: sourceTypeInput || matched.sourceType || 'user_explicit',
    createdAt: matched.createdAt || nowIso,
    updatedAt: nowIso,
    lastAccessedAt: nowIso,
    embedding: newEmbStr,
    schemaVersion: '1.0'
  };

  return [{
    json: {
      operationType: 'update',
      sheetId,
      row_number: matched.row_number,
      memory: updatedRow,
      response: 'Successfully updated memory: "' + updatedRow.content + '".',
      ...updatedRow
    }
  }];
}

// ACTION: FORGET / DELETE / ARCHIVE
if (action === 'forget' || action === 'delete' || action === 'archive' || action === 'remove') {
  let matched = null;
  if (memoryIdInput) {
    matched = existingMemories.find(m => m.memoryId === memoryIdInput && m.status !== 'archived');
  } else if (topicInput) {
    const cleanTopic = topicInput.toLowerCase();
    matched = existingMemories.find(m => (m.status !== 'archived') && (
      (m.content || '').toLowerCase().includes(cleanTopic) ||
      (m.memoryType || '').toLowerCase() === cleanTopic
    ));
  }

  if (!matched) {
    return [{
      json: {
        operationType: 'read_only',
        success: false,
        status: 'NOT_FOUND',
        response: '⚠️ No active memory found matching "' + (topicInput || memoryIdInput) + '".'
      }
    }];
  }

  const updatedRow = {
    row_number: matched.row_number,
    memoryId: matched.memoryId,
    memoryType: matched.memoryType,
    content: matched.content,
    structuredValue: matched.structuredValue || '',
    status: 'archived',
    confidence: matched.confidence || 1.0,
    sourceMessageId: matched.sourceMessageId || '',
    sourceType: matched.sourceType || 'user_explicit',
    createdAt: matched.createdAt || nowIso,
    updatedAt: nowIso,
    lastAccessedAt: nowIso,
    embedding: matched.embedding || '',
    schemaVersion: '1.0'
  };

  return [{
    json: {
      operationType: 'update',
      sheetId,
      row_number: matched.row_number,
      memory: updatedRow,
      response: '🗑️ Memory forgotten: "' + matched.content + '".',
      forgottenId: matched.memoryId,
      ...updatedRow
    }
  }];
}

// Fallback
return [{
  json: {
    operationType: 'read_only',
    success: false,
    status: 'UNKNOWN_ACTION',
    response: 'Unknown action "' + action + '". Supported actions: retrieve, write, update, forget.'
  }
}];

const proc = $('Process Memory Action').first().json;
return {
  json: {
    success: true,
    status: 'CREATED',
    action: 'write',
    response: proc.response,
    memory: proc.memory
  }
};

const proc = $('Process Memory Action').first().json;
return {
  json: {
    success: true,
    status: 'UPDATED',
    action: proc.action || 'update',
    response: proc.response,
    memory: proc.memory
  }
};

const proc = $('Process Memory Action').first().json;
return {
  json: proc
};
